def is_hamiltonian(G):
    n = len(G)
    path = [0]*n

    def backtrack(index):
        nonlocal path
        if index == n:
            return True

        for node in range(n):
            if not path[node] and connect(G, path, index, node):
                path[node] = 1
                if backtrack(index + 1):
                    return True
                path[node] = 0

        return False

    def connect(G, path, current_node, target_node):
        nonlocal path
        if G[current_node][target_node] and not path[target_node]:
            path[target_node] = 1
            if target_node < current_node:
                # Go down in time
                return backtrack(target_node + 1)
            else:
                # Go up in time
                return backtrack(target_node + 1) or (path[current_node] and connect(G, path, current_node, target_node)) or connect(G, path, target_node, current_node)
        return False

    return backtrack(0)

