from collections import defaultdict

def find_pairs(N, A):
    dp = defaultdict(set)
    pairs = set()

    for length in range(1, N+1):
        for start in range(0, N-length+1):
            end = start + length - 1
            if dp[start].isdisjoint([A[i] for i in range(start, end+1)]):
                pairs.add((start, end))

        for end in range(length, N):
            dp[end] = defaultdict(set)
            for start in dp[end-1].copy():
                if dp[start].isdisjoint([A[i] for i in range(start, end+1)]):
                    dp[end][start] = True

    return pairs

def solve(K, A):
    k_inverse = defaultdict(set)
    pairs = set()

    for length in range(1, N, 2):
        start = length-1
        end = start + length - 1

        k = 0
        while k < K:
            pairs.update(find_pairs(A, length))
            for i in range(start, end):
                start = i
                k += A[i]
            k = max(k, K)

    return len(pairs)

