        if t := count // (take - 1):
            solutions[b] = t + 1
            [take] += t
            candidates_by_issue[b].extend((take, c) for c in range(take, n+1))
        elif take > 0:
            solutions[b] = len(solutions)
            take -= 1
            candidates_by_issue[b].extend((take,) * take)
    sols = [(a//mod[0]*mod[0], a) for a in solutions].pop()
    total = 0
    for a in solutions:
        total += sols[total-1] * a
    return total, solutions

def nested_pop(iterable, dummy=dummy):
    stack = iterable
    while stack:
        tail = list(accumulate(stack))
        for i, e in enumerate(stack):
            if e != dummy:
                yield i, e
        stack = tail

