def euler_totient(n):
    phi = n
    p = 2
    while p ** 2 <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            phi -= phi // p
        p += 1
    if n > 1:
        phi -= phi // n
    return phi

