from collections import defaultdict

def build_tree(D):
    N = len(D)
    edges = []
    degree = defaultdict(int)
    for i in range(1, N, 1):
        degree[D[i]] += 1
    root = None
    for i in range(1, N, 1):
        if degree[D[i]] == 1 and not (root == None):
            root = i
            break
        elif degree[D[i]] > 1 and not (root == None):
            root = i
            break
    if root == None:
        return -1
    degrees = sorted(set(D))
    root_index = degrees.index(D[root])  # Find the index of root in the sorted list
    for i in range(N):
        expr = i
        for j in range(N):
            if i == j:
                break
            expr += 1 if D[j] < D[root] else -1
        if D[root] == root_index:
            if expr > 2 * N:
                return -1
            edges.append((i + 1, root))
        elif D[root] == len(degrees) - 1:
            if expr < -(2 * N - 1):
                return -1
            edges.append((root, i + 1))
    return edges

