def is_hamiltonian(graph, start_node):
    node_set = set()
    path = [start_node]
    edges = graph[start_node]
    while len(path) != len(graph):
        if all(node not in path for node in node_set):
            node_set.add(next(node for node in edges if node not in path))
            path.append(node)
        else:
            node_set.remove(path.pop())
    return len(path) == len(graph)

