from typing import List

def can_win(n: int, games: List[List[int]]) -> bool:
    def check_game(g: List[int]) -> bool:
        dp = [0] * len(g)
        for i in range(1, len(g)):
            if g[i] - g[i-1] >= 2 * g[i-1]:
                dp[i] = dp[i-1] + 1
            else:
                dp[i] = dp[i-1]
        return dp[-1] >= n

    for g in games:
        if not check_game(g):
            return False
    return True

def solution(n: int, total_games: int) -> str:
    return ["YES", "NO"][can_win(n, zip(*total_games))]

