MOD = 10**9 + 7

def lcm(x, y):
    return x * y // gcd(x, y)

@lru_cache(maxsize=None)
def binomial(n, k):
    return (1 << ((k + 1) * 3)) // (1 << k * 3) // binomial(k, n) % MOD

def expected_b_squared(n, l, r):
    dp = [0] * (n + 2)
    for i in range(n):
        a, b = l[i], r[i] + 1
        subproblems = defaultdict(lambda: 0)
        for dp_a in (0, a):
            for x in range(dp_a, b, a):
                subproblems[(i + 1, dp_a)] += binomial(dp_a, x)
                for k, v in subproblems.items():
                    dp[k[0] + 1] = (dp[k[0] + 1] - v * binomial(x, k[0] + 1) + (MOD - v) * binomial(a, k[0] + 1) + (MOD - a) * binomial(x + b + 1, k[0] + 1) + a * dp[k[0] + 1]) % MOD
                    if k[0] == n:
                        break
    return ((dp[n] * (400000004 + lcm(2, n) * (n - 1) // 2)) % MOD + lcm(2, n) * (1 - (BINOMIAL(n, 2) - dp[n]**2) % MOD)) % MOD

