from typing import List

def find_stable_plan(n: int, costs: List[List[int]]) -> List[int]:
    visited = [False] * n
    edges = [[-1] * n for _ in range(n)]
    cost_diff = [[float('inf')] * n for _ in range(n)]

    def dfs(city: int, prev_city: int, cost_diff: int, edges: List[List[int]]) -> None:
        visited[city] = True
        for nxt in range(n):
            if nxt != prev_city and not visited[nxt] and cost_diff[nxt] > cost_diff[city] + costs[city][nxt]:
                cost_diff[nxt] = cost_diff[city] + costs[city][nxt]
                edges[nxt][city] = nxt
                edges[city][nxt] = nxt
                dfs(nxt, city, cost_diff[nxt], edges)

    n都市 = n

    for i in range(n):
        edges[i][i] = -1
        for j in range(n - 1):
            edges[i][i + 1] = costs[i][i + 1]
            if edges[i][i + 1] < edges[i + 1][i + 2]:
                edges[i + 1][i + 2] = costs[i + 1][i + 2]
                edges[i + 2][i] = edges[i + 1][i + 2]
            if edges[i + 1][i + 2] > cost_diff[i + 2]:
                cost_diff[i + 2] = edges[i + 1][i + 2]

    for i in range(n):
        if visited[i]:
            continue
        dfs(i + 1, -1, float('inf'), edges)

    plan = [-1] * n
    for i in range(n):
        for j in range(n):
            if i == j and edges[i][j] == -1:
                dfs(i, -1, float('inf'), edges)
                if edges[i][j] == -1:
                    return [i + 1] * n
                else:
                    plan[i] = j
            elif edges[i][j] == -1:
                return [i + 1] * n
            while edges[i][j] != -1:
                plan[edges[i][j]] = j
                j = i

    return "#" + "".join(str(c) for c in plan)

