from collections import defaultdict, deque

def find_stable_pairing(N, adjacency_cost):
    graph = defaultdict(list)
    reachable = defaultdict(set)

    # Build the graph
    for i in range(1, N):
        for j in range(1, N):
            if adjacency_cost[i][j] != 0:
                graph[i].append(j)
                graph[j].append(i)
                reachable[i].add(j)
                reachable[j].add(i)

    # BFS to find the maximum diameter of the graph
    queue = deque([(-1, -1)])
    while queue:
        (d, u) = queue.popleft()
        for v in graph[u]:
            if v not in reachable[-d]:
                reachable[-d-1].add(v)
                queue.append((-d-1, v))

    # Check for stable pairing
    for res in [-1] + straight_path_sum(reachable, N // 2):
        if res == -1:
            return [-1] + straight_path_sum(reachable, N // 2)

    return res

def straight_path_sum(parent, n, memo=None):
    if n in parent: 
        memo[n] = get_cost_for_pair(parent[n][0], parent, n)
    if n in memo: 
        return memo[n]

    total_cost = 0
    for child in parent[n]:
        total_cost += memo.get(child, get_cost_for_pair(child, parent, n))
    return total_cost

def get_cost_for_pair(p1, parent, n):
    if len(parent[p1]) == 1: 
        return 0
    tmp = parent[p1][1:]
    for i in range(len(tmp)):
        if parent[p1][i] in tmp:
            tmp.pop(tmp.index(parent[p1][i]))
    return sum(parent[p1]) + linear_sum(tmp, parent)

def linear_sum(s, parent):
    memo = defaultdict(int)
    sum_s = []
    memo[0] = parent[1][0]

    queue = deque(parent[1][1:])

    while queue:
        node = queue.popleft()
        if node != s:
            memo[node] = memo[parent[node][0]] + parent[node][1]
            queue.extend(parent[node][1:])
    return sum_s[:]
