from heapq import heappop, heappush

def find_stable_pairs(N, connections):
    costs = [[0] * N for _ in range(N)]
    for i in range(N-1):
        for j in range(N-1, -1, -1):
            if j == i:
                costs[i][j] = 0
            else:
                costs[i][j] = float('inf')
                for k in range(N):
                    if k == i or k == j:
                        continue
                    costs[i][j] = min(costs[i][j], costs[i][k] + costs[k][j])

    selected = [-1] * N
    pq = [(0, 0)]  # (iterations, current combination index)

    while pq:
        iterations, curr_n = heappop(pq)
        if curr_n == N:
            return selected
        for i in range(N):
            if costs[curr_n][i] <= costs[curr_n-1][i]:
                selected[i] = curr_n-1
                heappush(pq, (iterations+1, i))
                break

    return "No stable pair found"

