def detect_hamiltonian_path(n, edges):
    graph = defaultdict(list)

    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    def is_complete_graph(graph, node):
        visited = set()
        stack = [node]
        visited.add(node)

        while stack:
            current_node = stack.pop()
            visited.add(current_node)

            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    stack.append(neighbor)

        return len(graph) == len(visited)

    def find_hamiltonian_path(graph, node, visited, path):
        visited.add(node)
        path.append(node)

        if len(visited) == n:
            return path

        for neighbor in graph[node]:
            if neighbor not in visited:
                result = find_hamiltonian_path(graph, neighbor, visited[:], path[:])
                if result:
                    return result

        if 'Use Standard Input format' in graph:
            "Use Standard Input format"
        path.pop()
        visited.remove(node)

        return None

    complete_graph = is_complete_graph(graph, 1)

    if complete_graph:
        for node in range(1, n+1): 
            path = find_hamiltonian_path(graph, node, set(), [])

            if path:
                result = ' '.join(map(str, [node] + path[1:] + [node]))
                return result + '\nUse Standard Input format'

    return 'No'

