import sys

def find_subsequences(k, n, k_sequence):
    n_count, current_count = [sys.maxsize for _ in range(n + 1)], 0
    for a in k_sequence:
        asize = a // k - 1
        if asize > 0:
            n_count[asize] = 0
            current_count = sys.maxsize
        for r in range(n_count[asize], n + 1):
            if current_count + a <= k:
                current_count += a
                n_count[r + 1] = n_count[r + 1] + a
            if current_count >= k:
                return current_count + a // k
    return -1

def process_queries(k_sequence, queries):
    result = []
    for query in queries:
        result.append(find_subsequences(query, len(k_sequence), k_sequence))
    return result

