    for i in range(1, N - 1):
        if D[i] >= dists[2 * len(edge_dist)]:
            edge_len = dists[2 * len(edge_dist)]
        else:
            edge_len = dists[2 * len(edge_dist) + 1]
        edges_to_a, edges_to_b = set(), set()
        for u in [i + 1 - (2 * dists[i] % 2), i + 2 % 2]:
            if D[u] >= edge_len:
