                tree.append(min(u, i), max(u, i))
                edge_dist[(min(u, i), max(u, i))] = edge_len
            else:
                edges_to_b.add(edge_dist.get((2 * dists[u] - edge_len + 1, 2 * dists[u]), (2 * dists[u], 2 * dists[u] + 1)))
                tree.append(2 * dists[u], 2 * dists[u] + 1)
                edge_dist[(2 * dists[u], 2 * dists[u] + 1)] = edge_len
        if len(edges_to_a) >= len(edges_to_b):
            for el in edges_to_a:
                tree.append(*el)
        else:
            for el in edges_to_b:
                tree.append(*el)

    return tree

