from collections import defaultdict

def is_hamiltonian_path_exists(graph):
    """
    Function to determine if there exists a Hamiltonian path in a given non-directed graph.
    Returns True if a Hamiltonian path exists, False otherwise.
    """
    for start_node in range(1, len(graph) + 1):
        stack = [start_node]
        visited = set(stack)
        while stack:
            current_node = stack.pop()
            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)
                    if len(visited) == len(graph) - 1:
                        # If all nodes are visited, check if the path goes through an unvisited node
                        if any(neighbor not in visited for neighbor in graph if neighbor != current_node):
                            return True
        if len(visited) == len(graph) - 2:
            # If the last node visited has already been visited, it forms a path
            return True
    return False

