class XORSum:
    def __init__(self):
        self.mod = 998244353
        self.max_val = (1 << 31) - 1

    def find_possible_parts(self, segment1, segment2):
        if segment1 == segment2:
            return segment1
        else:
            return segment1 ^ segment2

    def bitwise_xor_sum(self, segment1, segment2):
        result = 0
        for a in segment1:
            for b in segment2:
                result += self.find_possible_parts(a | b, a ^ b)
                result %= self.mod
        return result

