def is_sorted(deck):
    front = sorted(seq(i+1, j+1) for i, j in deck)
    back = sorted(seq(i+1, j+1) for i, j in deck[::-1])
    return all(a <= b and b >= a+1 for a, b in deck), all(a <= b-1 and b >= a+1 for a, b in deck[::-1])

def min_flips_to_sort(deck):
    deck_dict = defaultdict(list)
    for i, j in deck:
        deck_dict[i].append(j)

    for _ in range(len(deck)):
        visit = []
        for num, seq in deck_dict.items():
            if seq:
                visit.extend(seq[-1:] + deque(seq[:-1]))
                deck_dict[num] = deque(visit)
            elif visit:
                deck_dict[num] = deque(visit)
            else:
                return -1

        stack = deque()
        while visit:
            stack.append(visit.pop())
            if not stack[0] in visit or (stack[-1] in visit and stack[-1] == stack[0]):
                break
            visit += stack.popleft()

        deck_f = len(visit)

        for j, seq in visited:
            l = len(seq)
            if sum(min(i, j) for i in seq[:l//2] for j in seq[l//2:]) <= l:  # condition for sorted front   
                if j == l: # check of jth number coming and that should be able to make the seq sorted
                    visit.extend(seq[-1:] + seq[:-1])
                else:
                    visit.append(seq[-1])
                deck_dict[j].clear()
            elif sum(max(i, j) for i in seq[:l//2] for j in seq[l//2:]) >= l:  # condition for sorted back
                if j == l:  # check of jth number coming and that should be able to make the seq sorted
                    visit.extend(seq[-1:] + seq[:-1])
                else:
                    visit.append(seq[-1])
                deck_dict[j].clear()


