import sys

class Tree:
    def __init__(self, size) -> None:
        self.size = size
        self.negative = False

    def reset(self):
        self.parents = [-1] * self.size
        self.visited = []
        self.dist = [-1] * self.size

    def add_edge(self, u, v):
        self.parents[u] = v

    def getsize(self, v):
        return 1 + self.sumdist(v)

    def sumdist(self, v):
        return sum([self.finddist(i) for i in self.visited])

    def finddist(self, v):
        dist = self.dist[v]
        if dist < 0:
            dist = self.search(v)
        return dist

    def search(self, v):
        if self.negative:
            return self.search(self.parents[v]) + 1

        if self.visited[v] == False:
            self.visited[v] = True
            for i in self.parents[i]:
                self.search(i)    
        for i in self.parents[i]:
            self.search(i)
        return None

        return dist

    def is_critical(self, k, w):
        t = Tree(self.size)
        for i in range(self.size):
            if not t.visited[i] and self.finddist(i) != k:
                return False
        w -= 2
        for i in range(self.size):
            if self.finddist(i) == k:
                w -= 1
        return True

