import sys

def is_sorted(deck):
    a_values = sorted(deck[::2])
    b_values = sorted(deck[1::2], reverse=True)
    return a_values == list(deck[::2]) and b_values == list(deck[1::2])

def min_flips(deck):
    n = len(deck)
    count = 0
    for i in range(n):
        if deck[i][0] < deck[(i+1)//2][1]:
            j = 2 * i + 1
            while j < n and deck[j][0] > deck[(j+1)//2][1]:
                j += 2
            if j == n:
                return -1
            count += j - i - 1
    return count

n = int(input())
deck = [list(map(int, input().split())) for _ in range(n)]

if is_sorted(deck):
    print(0)
else:
    print(min_flips(deck))
